{
  "paragraphs": [
    {
      "component_id": "concern_001",
      "text": "Where an employee is in regular employment, the Labor Code provides that the employer may not terminate the employee except for a just cause or an authorized reason; if the dismissal is not for a just cause, it is deemed unjust and the employee may be reinstated with full backwages, seniority rights and other benefits from the time compensation was withheld.",
      "evidence": [
