      ]
    },
    {
      "component_id": "concern_002",
      "text": "A retailer must publicly display a price tag, label or marking for each consumer product, and the product may not be sold for more than the price shown; if a tag cannot be placed because of size or nature, a nearby price list may suffice, and no erasures or alterations of the price tag are allowed.",
      "evidence": [
        { "quote_id": "concern_002.s1.q1" },
