{
  "paragraphs": [
    {
      "component_id": "concern_001",
      "text": "For a covered employee, any withholding of wages is unlawful unless the worker consents. Deductions are only allowed when the employer’s business recognizes such practice and the employee is clearly shown responsible for the loss, is given a reasonable chance to be heard, the deduction is fair and does not exceed the actual loss, and the amount taken never surpasses 20 % of the employee’s weekly wages.",
      "evidence": [
        { "quote_id": "concern_001.s1.q1" },
        { "quote_id": "concern_001.s2.q1" },
        { "quote_id": "concern_001.s2.q2" }
      ]
    },
    {
      "component_id": "concern_002",
      "text": "A business establishment must give the exact change to the consumer; it is unlawful to shortchange even a small amount. If the establishment fails or refuses to give the proper change, it must pay the complainant the total amount of change owed in addition to any fine imposed by the authorities.",
      "evidence": [
        { "quote_id": "concern_002.s2.q2" },
        { "quote_id": "concern_002.s1.q2" },
        { "quote_id": "concern_002.s1.q3" }
      ]
    }
